package ai.quranlab.tajweedformer

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test

/**
 * The shared settings vectors (config_vectors.json with calibration_fixture.json,
 * generated by settings_ref.py): every case's resolved JSON must equal the reference (thresholds
 * within 1e-9, dropped and refused identical), and every app_invalid case must throw.
 */
class TajweedSettingsTest {
    private fun resource(name: String): String =
        javaClass.getResourceAsStream("/tajweed/$name")!!.use { it.readBytes().toString(Charsets.UTF_8) }

    private val calibration by lazy { Calibration.parse(resource("calibration_fixture.json")) }

    @Suppress("UNCHECKED_CAST")
    private val vectors by lazy { Json.parse(resource("config_vectors.json")) as Map<String, Any?> }

    /** Deep equality of parsed JSON, numbers within 1e-9; returns the first difference or null. */
    private fun diff(path: String, want: Any?, have: Any?): String? {
        when {
            want is Map<*, *> && have is Map<*, *> -> {
                if (want.keys != have.keys) return "$path: keys ${want.keys} != ${have.keys}"
                for (k in want.keys) diff("$path.$k", want[k], have[k])?.let { return it }
                return null
            }
            want is List<*> && have is List<*> -> {
                if (want.size != have.size) return "$path: $want != $have"
                for (i in want.indices) diff("$path[$i]", want[i], have[i])?.let { return it }
                return null
            }
            want is Double && have is Double -> return if (Math.abs(want - have) <= 1e-9) null else "$path: $want != $have"
            else -> return if (want == have) null else "$path: $want != $have"
        }
    }

    @Test
    fun everyCaseMatchesTheReference() {
        val cases = vectors["cases"] as List<*>
        assertEquals(39, cases.size)
        val failures = ArrayList<String>()
        for (c in cases) {
            c as Map<*, *>
            val name = c["name"] as String
            val remote = RemoteTajweed.parse(c["remote"])
            val app = TajweedOptions.fromMap(c["app"])
            val backend = TajweedBackend.fromKey(c["backend"] as String)!!
            val got = TajweedSettings.resolve(calibration, remote, app, debug = c["debug"] as Boolean, backend = backend)
            // through the JSON text, as an app would compare it
            val have = Json.parse(got.toJson())
            diff(name, c["expect"], have)?.let { failures.add(it) }
        }
        assertTrue(failures.joinToString("\n"), failures.isEmpty())
    }

    @Test
    fun theComparisonSeesADifference() {
        val c = (vectors["cases"] as List<*>)[1] as Map<*, *>
        val have = Json.parse(TajweedSettings.resolve(calibration, RemoteTajweed.parse(c["remote"]), debug = false).toJson())
        assertEquals(null, diff("x", c["expect"], have))
        @Suppress("UNCHECKED_CAST")
        val sites = (have as MutableMap<String, Any?>)["sites"] as MutableMap<String, MutableMap<String, Any?>>
        sites.getValue("cons_sub")["threshold"] = 1.75 + 2e-9
        assertTrue(diff("x", c["expect"], have) != null)
        sites.getValue("cons_sub")["threshold"] = 1.75
        (have["refused"] as MutableList<Any?>).clear()
        assertTrue(diff("x", c["expect"], have) != null)
    }

    @Test
    fun everyInvalidAppOptionThrows() {
        val inv = vectors["app_invalid"] as List<*>
        assertEquals(8, inv.size)
        for (c in inv) {
            c as Map<*, *>
            assertEquals("invalid_app_option", c["expect_error"])
            try {
                TajweedSettings.resolve(calibration, RemoteTajweed.ABSENT, TajweedOptions.fromMap(c["app"]), debug = false)
                fail("${c["name"]} did not throw")
            } catch (e: RecognizerException.InvalidAppOption) {
                assertEquals("invalid_app_option", e.code)
            }
        }
    }

    @Test
    fun remoteBlockFromTextNeverThrows() {
        for (text in listOf("", "{", "[1,2]", "null", "\"x\"", "{\"v\":1,\"preset\":NaN}", "{\"v\":1,\"overrides\":{\"cons_sub\":{\"threshold\":Infinity}}}")) {
            val r = RemoteTajweed.parseJson(text)
            TajweedSettings.resolve(calibration, r, debug = false)
        }
        assertEquals(listOf("remote"), RemoteTajweed.parseJson("{").dropped)
        assertEquals(listOf("remote.overrides.cons_sub"),
            RemoteTajweed.parseJson("{\"v\":1,\"overrides\":{\"cons_sub\":{\"threshold\":Infinity}}}").dropped)
        assertEquals(listOf("remote.preset"), RemoteTajweed.parseJson("{\"v\":1.0,\"preset\":NaN}").dropped)
        assertFalse(RemoteTajweed.parseJson("null").present)
        // the block inside a whole /v1/config document
        val doc = "{\"models\":[],\"tajweed\":{\"v\":1,\"preset\":\"strict\",\"context\":\"c24_l72\"}}"
        val r = RemoteTajweed.fromConfigJson(doc)
        assertEquals(TajweedPreset.STRICT, r.preset)
        assertEquals("c24_l72", TajweedSettings.resolve(calibration, r, debug = false).context)
        assertFalse(RemoteTajweed.fromConfigJson("{\"models\":[]}").present)
    }

    @Test
    fun typedAppOptions() {
        val s = TajweedSettings.resolve(
            calibration,
            RemoteTajweed.parseJson("{\"v\":1,\"preset\":\"strict\",\"checks\":{\"qalqalah\":true}}"),
            TajweedOptions(overrides = mapOf(SiteClass.CONS_SUB to ClassOverride.threshold(-1.5)), checks = mapOf(TajweedCheck.QALQALAH to false)),
            debug = false,
        )
        assertEquals(-1.5, s.sites.getValue(SiteClass.CONS_SUB).threshold!!, 0.0)
        assertEquals(SettingSource.APP, s.sites.getValue(SiteClass.CONS_SUB).source)
        assertEquals(null, s.sites.getValue(SiteClass.CONS_SUB).preset)
        assertEquals(3.0, s.sites.getValue(SiteClass.CONS_DEL).threshold!!, 1e-12) // the remote preset, strict
        assertEquals(SettingSource.REMOTE, s.sites.getValue(SiteClass.CONS_DEL).source)
        assertEquals(TajweedPreset.STRICT, s.sites.getValue(SiteClass.CONS_DEL).preset)
        assertFalse(s.qalqalah.enabled)
        for (bad in listOf(Double.NaN, Double.POSITIVE_INFINITY, 20.000001, -25.0)) {
            try {
                ClassOverride.threshold(bad)
                fail("threshold $bad accepted")
            } catch (e: RecognizerException.InvalidAppOption) {
            }
        }
        try {
            TajweedPreset.of("loud")
            fail()
        } catch (e: RecognizerException.InvalidAppOption) {
        }
        try {
            TajweedSettings.resolve(calibration, app = TajweedOptions(context = "c16_l256"), debug = true)
            fail()
        } catch (e: RecognizerException.InvalidAppOption) {
        }
    }

    @Test
    fun calibrationFixtureReads() {
        assertEquals("v4.0", calibration.modelId)
        assertEquals("c16_l64", calibration.defaultContext)
        assertEquals(TajweedPreset.BALANCED, calibration.defaultPreset)
        assertEquals(SiteClass.entries.toList(), calibration.classes)
        assertEquals(listOf("c16_l64", "c24_l72"), calibration.contexts.keys.toList())
        val c = calibration.context("c16_l64")
        assertEquals(0.5, c.fusionWeight(SiteClass.CONS_SUB), 0.0)
        assertEquals(0.8, c.fusionWeight(SiteClass.VOWEL_SUB), 0.0)
        assertEquals(CheckStatus.OFF, c.madd.lazimStatus)
        assertEquals(0.2556, c.qalqalah.number("tau")!!, 0.0)
        assertEquals(1.0, c.threshold(SiteClass.VOWEL_SUB, TajweedPreset.BALANCED)!!, 1e-12)
        assertEquals(2.5, c.threshold(SiteClass.CONS_SUB, TajweedPreset.BALANCED, TajweedBackend.FP32)!!, 1e-12)
        assertEquals(0.15, c.qalqalah.tau(TajweedPreset.STRICT)!!, 0.0)
        assertEquals(null, calibration.context("c24_l72").threshold(SiteClass.LONG_TO_SHORT, TajweedPreset.VERY_SENSITIVE))
        for (bad in listOf("{}", "[]", "{\"format\":\"quranlab.tajweed-calibration/2\"}", "not json")) {
            try {
                Calibration.parse(bad)
                fail("$bad accepted")
            } catch (e: RecognizerException.CalibrationInvalid) {
            }
        }
    }
}
